import { test, expect } from '@playwright/test';

test.describe('Password Reset Confirmation Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/password-reset');
  });

  test('should display confirmation message after successful password reset', async ({ page }) => {
    // Setup: intercept the API call to reset password
    await page.route('**/api/password-reset/confirm', (route) => {
      route.continue();
    });

    // Intercept the API call to verify the password reset
    await page.route('**/api/password-reset/verify', (route) => {
      route.continue();
    });

    // Verify the reset form is visible
    const resetForm = page.getByRole('form', { name: /reset password/i });
    await expect(resetForm).toBeVisible();

    // Fill in the email field
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    // Fill in the new password field
    const newPasswordInput = page.getByLabel(/new password/i);
    await newPasswordInput.fill('NewSecurePassword123!');

    // Fill in the confirm password field
    const confirmPasswordInput = page.getByLabel(/confirm password/i);
    await confirmPasswordInput.fill('NewSecurePassword123!');

    // Click the reset button
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait for the confirmation message to appear
    const confirmationMessage = page.getByText(/password has been reset successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify the success message is displayed
    await expect(confirmationMessage).toContainText('Password has been reset successfully');

    // Verify the user is redirected to the homepage
    await expect(page).toHaveURL(/^\/.*$/);
  });

  test('should not display confirmation message if password reset fails', async ({ page }) => {
    // Setup: intercept the API call to reset password with a failure response
    await page.route('**/api/password-reset/confirm', (route) => {
      route.abort('failed');
    });

    // Intercept the API call to verify the password reset
    await page.route('**/api/password-reset/verify', (route) => {
      route.abort('failed');
    });

    // Verify the reset form is visible
    const resetForm = page.getByRole('form', { name: /reset password/i });
    await expect(resetForm).toBeVisible();

    // Fill in the email field
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    // Fill in the new password field
    const newPasswordInput = page.getByLabel(/new password/i);
    await newPasswordInput.fill('IncorrectPassword');

    // Fill in the confirm password field
    const confirmPasswordInput = page.getByLabel(/confirm password/i);
    await confirmPasswordInput.fill('IncorrectPassword');

    // Click the reset button
    const resetButton = page.getByRole('button', { name: /reset password/i });
    await resetButton.click();

    // Wait for the error message to appear
    const errorMessage = page.getByText(/password reset failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error message is displayed
    await expect(errorMessage).toContainText('Password reset failed');

    // Verify the form is still visible
    await expect(resetForm).toBeVisible();

    // Verify the user is not redirected
    await expect(page).toHaveURL(/^\/.*$/);
  });
});
